#include <future>
#include <memory>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    static_assert(
        std::uses_allocator<std::packaged_task<int()>, std::allocator<int>>::value,
        "Allocator-aware in C++11/14");
    std::packaged_task<int()> task{[] { return 7; }};
    auto result = task.get_future();
    task();
    assert(result.get() == 7);
}
